-- ═══════════════════════════════════════════════════════════════════════════\n-- PARENT NOTIFICATION SYSTEM - DATABASE MIGRATION\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Creates tables for comprehensive SMS notification logging and tracking\n-- ═══════════════════════════════════════════════════════════════════════════\n\nUSE school_management;\n\n-- Create parent notifications log table\nCREATE TABLE IF NOT EXISTS parent_notifications_log (\n  id INT PRIMARY KEY AUTO_INCREMENT,\n  parent_id INT,\n  student_id INT NULL,\n  application_id INT NULL,\n  notification_type ENUM('link_approved', 'manual_link', 'application_submitted', 'application_rejected', 'conduct_removal', 'leave_approval', 'custom_message') NOT NULL,\n  message TEXT NOT NULL,\n  phone_number VARCHAR(20) NOT NULL,\n  delivery_status ENUM('sent', 'failed', 'pending', 'retry') DEFAULT 'pending',\n  provider VARCHAR(50) NULL,\n  message_id VARCHAR(255) NULL,\n  error_message TEXT NULL,\n  retry_count INT DEFAULT 0,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  \n  INDEX idx_parent_id (parent_id),\n  INDEX idx_student_id (student_id),\n  INDEX idx_notification_type (notification_type),\n  INDEX idx_delivery_status (delivery_status),\n  INDEX idx_created_at (created_at),\n  \n  FOREIGN KEY (parent_id) REFERENCES users(id) ON DELETE CASCADE,\n  FOREIGN KEY (student_id) REFERENCES global_student_sheets(id) ON DELETE SET NULL,\n  FOREIGN KEY (application_id) REFERENCES parent_linking_applications(id) ON DELETE SET NULL\n);\n\n-- Enhance existing sms_queue table if it exists\nALTER TABLE sms_queue \nADD COLUMN IF NOT EXISTS provider VARCHAR(50) NULL AFTER status,\nADD COLUMN IF NOT EXISTS message_id VARCHAR(255) NULL AFTER provider,\nADD COLUMN IF NOT EXISTS sent_at TIMESTAMP NULL AFTER message_id,\nADD COLUMN IF NOT EXISTS retry_count INT DEFAULT 0 AFTER sent_at;\n\n-- Create indexes for better performance\nCREATE INDEX IF NOT EXISTS idx_sms_queue_status ON sms_queue(status);\nCREATE INDEX IF NOT EXISTS idx_sms_queue_created_at ON sms_queue(created_at);\nCREATE INDEX IF NOT EXISTS idx_sms_queue_phone ON sms_queue(phone_number);\n\n-- Create parent notification preferences table\nCREATE TABLE IF NOT EXISTS parent_notification_preferences (\n  id INT PRIMARY KEY AUTO_INCREMENT,\n  parent_id INT NOT NULL,\n  sms_enabled BOOLEAN DEFAULT TRUE,\n  email_enabled BOOLEAN DEFAULT TRUE,\n  whatsapp_enabled BOOLEAN DEFAULT FALSE,\n  conduct_notifications BOOLEAN DEFAULT TRUE,\n  attendance_notifications BOOLEAN DEFAULT TRUE,\n  grade_notifications BOOLEAN DEFAULT TRUE,\n  fee_notifications BOOLEAN DEFAULT TRUE,\n  leave_notifications BOOLEAN DEFAULT TRUE,\n  general_notifications BOOLEAN DEFAULT TRUE,\n  preferred_language ENUM('kinyarwanda', 'english', 'french') DEFAULT 'kinyarwanda',\n  quiet_hours_start TIME DEFAULT '22:00:00',\n  quiet_hours_end TIME DEFAULT '06:00:00',\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  \n  UNIQUE KEY unique_parent_preferences (parent_id),\n  FOREIGN KEY (parent_id) REFERENCES users(id) ON DELETE CASCADE\n);\n\n-- Create SMS statistics view\nCREATE OR REPLACE VIEW sms_statistics AS\nSELECT \n  DATE(created_at) as date,\n  notification_type,\n  delivery_status,\n  COUNT(*) as count,\n  COUNT(DISTINCT parent_id) as unique_parents,\n  COUNT(DISTINCT student_id) as unique_students\nFROM parent_notifications_log\nGROUP BY DATE(created_at), notification_type, delivery_status;\n\n-- Create daily SMS summary view\nCREATE OR REPLACE VIEW daily_sms_summary AS\nSELECT \n  DATE(created_at) as date,\n  COUNT(*) as total_notifications,\n  SUM(CASE WHEN delivery_status = 'sent' THEN 1 ELSE 0 END) as sent,\n  SUM(CASE WHEN delivery_status = 'failed' THEN 1 ELSE 0 END) as failed,\n  SUM(CASE WHEN delivery_status = 'pending' THEN 1 ELSE 0 END) as pending,\n  COUNT(DISTINCT parent_id) as unique_parents_contacted,\n  ROUND(SUM(CASE WHEN delivery_status = 'sent' THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) as success_rate\nFROM parent_notifications_log\nGROUP BY DATE(created_at)\nORDER BY date DESC;\n\n-- Insert default notification preferences for existing parents\nINSERT IGNORE INTO parent_notification_preferences (parent_id)\nSELECT id FROM users WHERE role = 'parent' AND is_active = 1;\n\n-- Create stored procedure for sending notifications\nDELIMITER //\n\nCREATE OR REPLACE PROCEDURE sp_log_parent_notification(\n  IN p_parent_id INT,\n  IN p_student_id INT,\n  IN p_application_id INT,\n  IN p_notification_type VARCHAR(50),\n  IN p_message TEXT,\n  IN p_phone_number VARCHAR(20),\n  IN p_delivery_status VARCHAR(20),\n  IN p_provider VARCHAR(50),\n  IN p_message_id VARCHAR(255)\n)\nBEGIN\n  DECLARE EXIT HANDLER FOR SQLEXCEPTION\n  BEGIN\n    ROLLBACK;\n    RESIGNAL;\n  END;\n  \n  START TRANSACTION;\n  \n  -- Insert notification log\n  INSERT INTO parent_notifications_log (\n    parent_id, student_id, application_id, notification_type, \n    message, phone_number, delivery_status, provider, message_id\n  ) VALUES (\n    p_parent_id, p_student_id, p_application_id, p_notification_type,\n    p_message, p_phone_number, p_delivery_status, p_provider, p_message_id\n  );\n  \n  -- Update parent last contact date\n  UPDATE users \n  SET updated_at = NOW() \n  WHERE id = p_parent_id;\n  \n  COMMIT;\nEND //\n\nDELIMITER ;\n\n-- Create function to get parent notification stats\nDELIMITER //\n\nCREATE OR REPLACE FUNCTION get_parent_notification_count(p_parent_id INT, p_days INT)\nRETURNS INT\nREADS SQL DATA\nDETERMINISTIC\nBEGIN\n  DECLARE notification_count INT DEFAULT 0;\n  \n  SELECT COUNT(*) INTO notification_count\n  FROM parent_notifications_log\n  WHERE parent_id = p_parent_id\n    AND created_at >= DATE_SUB(NOW(), INTERVAL p_days DAY)\n    AND delivery_status = 'sent';\n  \n  RETURN notification_count;\nEND //\n\nDELIMITER ;\n\n-- Create indexes for better query performance\nCREATE INDEX IF NOT EXISTS idx_parent_notifications_parent_date ON parent_notifications_log(parent_id, created_at);\nCREATE INDEX IF NOT EXISTS idx_parent_notifications_student_date ON parent_notifications_log(student_id, created_at);\nCREATE INDEX IF NOT EXISTS idx_parent_notifications_type_status ON parent_notifications_log(notification_type, delivery_status);\n\nSELECT 'Parent notification system migration completed successfully!' as status;